FOR EACH ROW
BEGIN
    INSERT INTO audit_logs (
        table_name, 
        record_id, 
        operation, 
        new_values,
        user_id,
        user_name
    ) VALUES (
        'users',
        NEW.id,
        'CREATE',
        JSON_OBJECT(
            'id', NEW.id,
            'name', NEW.name,
            'email', NEW.email,
            'phone_number', NEW.phone_number,
            'branch_id', NEW.branch_id,
            'is_active', NEW.is_active,
            'isAdmin', NEW.isAdmin
        ),
        @current_user_id,
        @current_user_name
    );
END */;;
DELIMITER ;
