CREATE TABLE `visits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `visitor_id` int(11) NOT NULL,
  `digital_card_no` varchar(10) DEFAULT NULL,
  `reason` varchar(255) NOT NULL,
  `office` varchar(255) NOT NULL,
  `branch_id` int(11) NOT NULL,
  `has_laptop` tinyint(1) DEFAULT 0,
  `laptop_brand` varchar(100) DEFAULT NULL,
  `laptop_model` varchar(100) DEFAULT NULL,
  `company` varchar(255) DEFAULT NULL,
  `person_in_charge` varchar(255) DEFAULT NULL,
  `photo` longblob DEFAULT NULL,
  `id_photo_front` longblob DEFAULT NULL,
  `id_photo_back` longblob DEFAULT NULL,
  `signature` longblob DEFAULT NULL,
  `sign_in_time` datetime NOT NULL,
  `sign_out_time` datetime DEFAULT NULL,
  `registered_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `other_items` text DEFAULT NULL COMMENT 'JSON array of other items carried by visitor',
  `visitee_name` varchar(255) DEFAULT NULL COMMENT 'Name of person being visited (optional)',
  PRIMARY KEY (`id`),
  KEY `registered_by` (`registered_by`),
  KEY `idx_visitor_id` (`visitor_id`),
  KEY `idx_branch_id` (`branch_id`),
  KEY `idx_sign_in_time` (`sign_in_time`),
  KEY `idx_digital_card_no` (`digital_card_no`),
  KEY `idx_visits_company` (`company`),
  KEY `idx_visits_person_in_charge` (`person_in_charge`),
  CONSTRAINT `visits_ibfk_1` FOREIGN KEY (`visitor_id`) REFERENCES `visitors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `visits_ibfk_2` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`),
  CONSTRAINT `visits_ibfk_3` FOREIGN KEY (`registered_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
